import{_ as o,o as t,c as i,a2 as a}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Customizing Invoice PDFs","description":"","frontmatter":{},"headers":[],"relativePath":"developer/pdf.md","filePath":"developer/pdf.md"}'),n={name:"developer/pdf.md"};function r(c,e,d,s,l,h){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="customizing-invoice-pdfs" tabindex="-1">Customizing Invoice PDFs <a class="header-anchor" href="#customizing-invoice-pdfs" aria-label="Permalink to &quot;Customizing Invoice PDFs&quot;">​</a></h1><p>FOSSBilling generates high-quality PDF invoices using a built-in Go rendering engine. You can customize the look and feel of these documents to match your brand.</p><hr><h2 id="🎨-branding-the-pdf" tabindex="-1">🎨 Branding the PDF <a class="header-anchor" href="#🎨-branding-the-pdf" aria-label="Permalink to &quot;🎨 Branding the PDF&quot;">​</a></h2><p>The simplest way to customize your invoices is through the <strong>Company Information</strong> settings in the Admin Portal:</p><ul><li><strong>Logo:</strong> Upload your &quot;Dark Logo&quot; (optimized for white backgrounds) to be displayed in the top header.</li><li><strong>Address:</strong> Your official company address will be rendered in the seller details section.</li><li><strong>Footer Text:</strong> Add legal notes or payment instructions.</li></ul><hr><h2 id="🏗️-technical-architecture" tabindex="-1">🏗️ Technical Architecture <a class="header-anchor" href="#🏗️-technical-architecture" aria-label="Permalink to &quot;🏗️ Technical Architecture&quot;">​</a></h2><p>The PDF generation logic resides in <code>pkg/pdf/</code>. It follows a structured template approach:</p><ul><li><strong>Layout Engine:</strong> Uses a coordinate-based positioning system for maximum precision.</li><li><strong>Font Support:</strong> Supports embedded Unicode fonts for international character rendering (RTL, CJK, etc.).</li><li><strong>Data Source:</strong> Injects a <code>domain.Invoice</code> and <code>domain.Client</code> object into the generator.</li></ul><hr><h2 id="🛠️-advanced-customization" tabindex="-1">🛠️ Advanced Customization <a class="header-anchor" href="#🛠️-advanced-customization" aria-label="Permalink to &quot;🛠️ Advanced Customization&quot;">​</a></h2><p>If you need to change the actual layout (e.g., move the tax column or add a custom field):</p><ol><li>Navigate to <code>backend-go/pkg/pdf/invoice_generator.go</code>.</li><li>Locate the drawing functions for headers, line items, and footers.</li><li>Modify the coordinates (<code>X</code>, <code>Y</code>) or font styles.</li><li>Rebuild the backend binary: <code>make build</code>.</li></ol><h3 id="dynamic-data" tabindex="-1">Dynamic Data <a class="header-anchor" href="#dynamic-data" aria-label="Permalink to &quot;Dynamic Data&quot;">​</a></h3><p>You can inject any field from the invoice or client record. If you have custom client attributes, ensure they are fetched in the <code>InvoiceService</code> before being passed to the PDF generator.</p><hr><h2 id="📄-pdf-specifications" tabindex="-1">📄 PDF Specifications <a class="header-anchor" href="#📄-pdf-specifications" aria-label="Permalink to &quot;📄 PDF Specifications&quot;">​</a></h2><ul><li><strong>Format:</strong> A4</li><li><strong>DPI:</strong> 72 (Standard PDF units)</li><li><strong>Security:</strong> Invoices are generated on-the-fly and never stored as files on the server for enhanced privacy.</li></ul>',19)])])}const g=o(n,[["render",r]]);export{p as __pageData,g as default};
